export const textKey=v=>String(v??'').normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();
export function searchApu(catalog,query,limit=40){const words=textKey(query).split(/\s+/).filter(Boolean);return catalog.parts.filter(p=>words.every(w=>textKey([p.code,p.description,...p.chapterPath,...p.operations.map(o=>o.label)].join(' ')).includes(w))).slice(0,limit);}
export function apuSnapshot(catalog,partId,operationId=null){const p=catalog.parts.find(p=>p.id===partId),o=operationId?p?.operations.find(o=>o.id===operationId):null;if(!p?.selectable||operationId&&!o?.selectable)throw Error('Partida u operación pendiente de validación o no ejecutable.');return {version:catalog.version,source:catalog.source,partId:p.id,code:p.code,description:p.description,unit:p.unit,unitOriginal:p.unitOriginal,validation:p.validation,operation:o?structuredClone(o):null};}
// Only references approved in the application registry are eligible; activity payloads cannot approve themselves.
export function apuRate(snapshot,registry=[]){const model=registry.find(r=>r.version===snapshot?.version&&r.operationId===snapshot?.operation?.id);if(!model||model.validation!=='approved'||!model.source||!['persona-dia','persona-hora','cuadrilla-dia','cuadrilla-hora'].includes(model.basis)||!(model.rate>0)||model.unit!==snapshot.unit)return null;return structuredClone(model);}

let cache;
export async function loadApu(){if(!cache)cache=(async()=>{const index=await fetch('./apu/index.json').then(r=>{if(!r.ok)throw Error('Catálogo APU no disponible');return r.json();});const bytes=await fetch('./apu/'+index.file).then(r=>{if(!r.ok)throw Error('Importación APU no disponible');return r.arrayBuffer();});const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(n=>n.toString(16).padStart(2,'0')).join('');if(hash!==index.sha256)throw Error('La importación APU cambió. Actualiza el catálogo antes de asociarla.');return JSON.parse(new TextDecoder().decode(bytes));})().catch(e=>{cache=null;throw e;});return cache;}
